// /app/app/mobile-pager.js — phone section pages + bottom dock.
//
// Under PHONE_QUERY every element tagged data-mpage belongs to one page;
// mobile-pager.css hides the others from body[data-mobile-page]. Nothing is
// moved in the DOM, so panels keep their lifecycle and the desktop grid is
// untouched. Containers that hold several pages list all of them
// (data-mpage="draw buy flip").
//
// Swiping sideways anywhere outside a horizontal control steps to the next or
// previous page; the dock tabs jump straight to one. The dock's last slot is
// Pending, condensed from the summary app-reveal-tray publishes. It is a button
// only while a tap would send a transaction or open a reveal (the tray's
// runNext); otherwise it is a status readout.

const PHONE_QUERY = '(max-width: 1099px)';
const PAGES = ['draw', 'buy', 'flip', 'quests', 'craps', 'degenerette', 'more'];
const STORAGE_KEY = 'mobilePager.page';
// A page that overflows by a little is scaled to fit; past this it scrolls.
const FIT_MIN_SCALE = 0.84;
const EDGE_GUARD_PX = 18;
const AXIS_LOCK_PX = 10;
const COMMIT_FRACTION = 0.22;
const COMMIT_VELOCITY = 0.35; // px per ms
const EDGE_RESISTANCE = 0.28;

const phone = typeof window.matchMedia === 'function'
  ? window.matchMedia(PHONE_QUERY)
  : { matches: false, addEventListener() {} };
const reducedMotion = typeof window.matchMedia === 'function'
  ? window.matchMedia('(prefers-reduced-motion: reduce)')
  : { matches: false };

const body = document.body;
const main = document.querySelector('main');
const dock = document.querySelector('.mpager-dock');
const pendingButton = dock?.querySelector('[data-mpager-pending]');
const scrollByPage = new Map();
let current = PAGES.includes(body.dataset.mobilePage) ? body.dataset.mobilePage : PAGES[0];
let transition = null;
let transitionVersion = 0;

function pageOf(element) {
  const host = element?.closest?.('[data-mpage]');
  if (!host) return null;
  const pages = host.getAttribute('data-mpage').trim().split(/\s+/);
  return pages.includes(current) ? current : pages[0];
}

function notifyPage(page) {
  document.dispatchEvent(new CustomEvent('mobile-pager:change', { detail: { page } }));
}

// The page-change listeners only refresh data (polls, the craps schedule,
// the event sheet); during a slide they landed on the frames that should be
// animating, so an animated switch tells them once it has finished.
function applyPage(page, { notify = true } = {}) {
  // On phones <main> is the scroller (mobile-pager.css app shell).
  scrollByPage.set(current, main.scrollTop);
  current = page;
  body.dataset.mobilePage = page;
  for (const tab of dock?.querySelectorAll('[data-mpager-tab]') || []) {
    if (tab.dataset.mpagerTab === page) tab.setAttribute('aria-current', 'true');
    else tab.removeAttribute('aria-current');
  }
  try { sessionStorage.setItem(STORAGE_KEY, page); } catch (_e) { /* private mode */ }
  // A fresh page opens at its top; a revisited page resumes.
  main.scrollTo({ top: scrollByPage.get(page) ?? 0, behavior: 'instant' });
  if (notify) notifyPage(page);
  scheduleFit();
}

// Off-page images are display:none, so the first frame of a slide onto their
// page waited on their decode (100+ ms on a Pixel 9). Once a page settles,
// decode its neighbours' images while the phone is idle.
const warmed = new WeakSet();
const idle = window.requestIdleCallback
  ? (fn) => window.requestIdleCallback(fn, { timeout: 1500 })
  : (fn) => setTimeout(fn, 300);

function warmNeighbours() {
  const index = PAGES.indexOf(current);
  const neighbours = [PAGES[index - 1], PAGES[index + 1]].filter(Boolean);
  idle(() => {
    for (const page of neighbours) {
      for (const img of document.querySelectorAll(`[data-mpage~="${page}"] img`)) {
        if (warmed.has(img) || !img.currentSrc && !img.src) continue;
        warmed.add(img);
        img.decode?.().catch(() => warmed.delete(img));
      }
    }
  });
}

function animate(offsetFrom, offsetTo, opacityFrom, opacityTo, duration) {
  if (!main?.animate) return Promise.resolve();
  const animation = main.animate([
    { transform: `translateX(${offsetFrom}px)`, opacity: opacityFrom },
    { transform: `translateX(${offsetTo}px)`, opacity: opacityTo },
  ], { duration, easing: 'cubic-bezier(.2,.7,.25,1)', fill: 'forwards' });
  return animation.finished.catch(() => {}).then(() => animation);
}

function clearDrag() {
  if (!main) return;
  main.style.transform = '';
  main.style.opacity = '';
  main.style.willChange = '';
  main.getAnimations?.().forEach((animation) => {
    if (animation.effect?.target === main) animation.cancel();
  });
}

export function showPage(page, { from = 0 } = {}) {
  if (!PAGES.includes(page)) return;
  // A dock tap should show its page immediately. Keep motion for an actual
  // swipe, but do not queue taps behind two slide animations (310ms each).
  if (from === 0 || !phone.matches || reducedMotion.matches || !main?.animate) {
    transitionVersion += 1;
    transition = null;
    clearDrag();
    if (page !== current) applyPage(page);
    warmNeighbours();
    return;
  }
  const version = ++transitionVersion;
  if (page === current) {
    if (from !== 0 && !reducedMotion.matches) {
      transition = animate(from, 0, 1, 1, 180).then(() => {
        if (version !== transitionVersion) return;
        clearDrag();
        transition = null;
      });
    } else clearDrag();
    return;
  }
  const direction = PAGES.indexOf(page) > PAGES.indexOf(current) ? 1 : -1;
  const width = window.innerWidth;
  const run = async () => {
    if (version !== transitionVersion) return;
    await animate(from, -direction * width * 0.35, 1 - Math.min(1, Math.abs(from) / width) * 0.4, 0, 120);
    if (version !== transitionVersion) return;
    clearDrag();
    applyPage(page, { notify: false });
    await animate(direction * width * 0.35, 0, 0, 1, 190);
    if (version !== transitionVersion) return;
    clearDrag();
    notifyPage(page);
    warmNeighbours();
  };
  transition = (transition || Promise.resolve()).then(run).finally(() => {
    if (version === transitionVersion) transition = null;
  });
}

function step(delta, from) {
  const next = PAGES[PAGES.indexOf(current) + delta];
  showPage(next || current, { from });
}

// Swipes that start inside something that owns horizontal motion stay there:
// range sliders, the Degenerette card carousel (touch-action pan-y), scratch
// surfaces (touch-action none), and any sideways scroller that actually
// overflows.
function blocksSwipe(target) {
  for (let el = target; el && el !== main && el.nodeType === 1; el = el.parentElement) {
    if (el.matches('input, select, textarea, [contenteditable], [data-no-page-swipe], [role="dialog"], dialog[open]')) return true;
    const style = getComputedStyle(el);
    const action = style.touchAction;
    if (action === 'none' || action === 'pan-y' || action === 'pinch-zoom') return true;
    if ((style.overflowX === 'auto' || style.overflowX === 'scroll')
      && el.scrollWidth > el.clientWidth + 1) return true;
  }
  return false;
}

let gesture = null;

function onTouchStart(event) {
  gesture = null;
  if (!phone.matches || event.touches.length !== 1) return;
  const touch = event.touches[0];
  if (touch.clientX < EDGE_GUARD_PX || touch.clientX > window.innerWidth - EDGE_GUARD_PX) return;
  if (blocksSwipe(event.target)) return;
  gesture = { x: touch.clientX, y: touch.clientY, t: event.timeStamp, axis: null, dx: 0 };
}

function onTouchMove(event) {
  if (!gesture || transition) return;
  const touch = event.touches[0];
  const dx = touch.clientX - gesture.x;
  const dy = touch.clientY - gesture.y;
  if (gesture.axis == null) {
    if (Math.hypot(dx, dy) < AXIS_LOCK_PX) return;
    gesture.axis = Math.abs(dx) > Math.abs(dy) * 1.2 ? 'x' : 'y';
    if (gesture.axis === 'x') main.style.willChange = 'transform';
  }
  if (gesture.axis !== 'x') return;
  if (event.cancelable) event.preventDefault();
  const atEdge = (dx > 0 && current === PAGES[0]) || (dx < 0 && current === PAGES.at(-1));
  gesture.dx = atEdge ? dx * EDGE_RESISTANCE : dx;
  gesture.lastT = event.timeStamp;
  main.style.transform = `translateX(${gesture.dx}px)`;
  main.style.opacity = String(1 - Math.min(0.35, Math.abs(gesture.dx) / window.innerWidth));
}

function onTouchEnd(event) {
  const done = gesture;
  gesture = null;
  if (!done || done.axis !== 'x') return;
  const elapsed = Math.max(1, (done.lastT ?? event.timeStamp) - done.t);
  const velocity = Math.abs(done.dx) / elapsed;
  const commit = Math.abs(done.dx) > window.innerWidth * COMMIT_FRACTION
    || (Math.abs(done.dx) > 40 && velocity > COMMIT_VELOCITY);
  main.style.transform = '';
  main.style.opacity = '';
  step(commit ? (done.dx < 0 ? 1 : -1) : 0, done.dx);
}

// Quest shortcuts and claim links call scrollIntoView on panels that may sit on
// another page. Switch to that page first so the native scroll has a target.
// Elements hidden by their own [hidden] state never pull the player away.
const nativeScrollIntoView = Element.prototype.scrollIntoView;
Element.prototype.scrollIntoView = function scrollIntoViewAcrossPages(...args) {
  if (phone.matches && !this.closest?.('[hidden]')) {
    const page = pageOf(this);
    if (page && page !== current) {
      clearDrag();
      applyPage(page);
    }
  }
  return nativeScrollIntoView.apply(this, args);
};

// ---- Condensed Pending ---------------------------------------------------

// Tab-width names for what is waiting. Mine FLIP is an action, not content,
// so it never appears here; it shows as the slot's tap action instead.
const SHORT_KIND = {
  tickets: 'TIX',
  lootbox: 'BOX',
  degenerette: 'DEGEN',
  'growth-claim': 'BET',
  'volume-claim': 'BET',
  'whale-pass-claim': 'PASS',
  decimator: 'DECI',
  baf: 'BAF',
  bingo: 'BINGO',
  'foil-match': 'FOIL',
  'foil-gold': 'FOIL',
  'affiliate-bonus': 'REF',
  'wwxrp-draw': 'WWXRP',
  craps: 'CRAPS',
};
const MINE_KINDS = new Set(['mass-resolution', 'batch-resolution']);
const pendingHead = pendingButton?.querySelector('[data-mpager-pending-head]');
const pendingFoot = pendingButton?.querySelector('[data-mpager-pending-foot]');
const idleHead = pendingHead?.innerHTML || '';

function contentGroups(items) {
  const groups = new Map();
  for (const item of items) {
    if (MINE_KINDS.has(item.kind)) continue;
    const name = SHORT_KIND[item.kind] || String(item.kind || 'ITEM').toUpperCase().slice(0, 5);
    const group = groups.get(name) || { name, count: 0, known: true };
    if (item.kind === 'tickets') {
      if (Number(item.tickets) > 0) group.count += Number(item.tickets);
      else group.known = false;
    } else group.count += Number(item.count) || 1;
    groups.set(name, group);
  }
  return [...groups.values()];
}

function renderPending(summary) {
  if (!pendingButton) return;
  const items = Array.isArray(summary?.items) ? summary.items : [];
  const next = summary?.next || null;
  const rng = summary?.rng || null;
  const groups = contentGroups(items);
  const busy = items.some((item) => item.state === 'busy');
  const mineOnly = groups.length === 0 && items.some((item) => MINE_KINDS.has(item.kind));
  const state = busy ? 'busy'
    : next ? 'ready'
      : groups.length > 0 || mineOnly || rng ? 'waiting' : 'idle';
  pendingButton.dataset.state = state;
  pendingButton.dataset.next = next?.kind && MINE_KINDS.has(next.kind) ? 'mine' : next?.kind || '';

  if (pendingHead) {
    pendingHead.textContent = '';
    if (groups.length > 0) {
      const [first, ...rest] = groups;
      const text = document.createElement('span');
      text.className = 'mpager-pend__text';
      text.textContent = first.known && first.count > 1 ? `${first.count} ${first.name}` : first.name;
      pendingHead.appendChild(text);
      if (rest.length > 0) {
        const more = document.createElement('span');
        more.className = 'mpager-pend__more';
        more.textContent = `+${rest.length}`;
        pendingHead.appendChild(more);
      }
    } else if (mineOnly) {
      const flame = document.createElement('img');
      flame.className = 'mpager-pend__flame';
      flame.src = '/whitepaper/flame-logo-split.svg';
      flame.alt = '';
      pendingHead.appendChild(flame);
    } else {
      pendingHead.innerHTML = idleHead;
    }
  }

  if (pendingFoot) {
    pendingFoot.textContent = '';
    pendingFoot.dataset.kind = '';
    if (busy) pendingFoot.textContent = 'WORKING';
    else if (next && MINE_KINDS.has(next.kind)) pendingFoot.textContent = 'MINE FLIP';
    else if (next?.kind === 'rng') pendingFoot.textContent = 'GET RNG';
    else if (next) pendingFoot.textContent = next.verb || 'OPEN';
    else if (rng) {
      pendingFoot.dataset.kind = 'rng';
      for (let index = 0; index < (Number(rng.steps) || 5); index += 1) {
        const dot = document.createElement('i');
        if (index < (Number(rng.complete) || 0)) dot.className = 'is-complete';
        pendingFoot.appendChild(dot);
      }
    } else pendingFoot.textContent = state === 'idle' ? 'PENDING' : 'WAITING';
  }

  const parts = groups.map((group) => (group.known ? `${group.count} ${group.name}` : group.name));
  if (busy) parts.push('working');
  else if (next) parts.push(`tap to ${pendingFoot?.textContent.toLowerCase() || 'open'}`);
  if (rng?.status) parts.push(rng.status.toLowerCase());
  pendingButton.setAttribute('aria-label', `Pending: ${parts.join(', ') || 'none'}`);
  // Only a real transaction or reveal makes the slot a control.
  pendingButton.disabled = !next || busy;
}

function tapPending() {
  document.querySelector('app-reveal-tray')?.runNext?.();
}

// ---- Fit to screen ---------------------------------------------------------

// Single-panel pages are one screen tall (mobile-pager.css). Live state (a
// FLIP balance row, a foil card, an error line) can push a panel a little past
// the screen; rather than scroll a few pixels, scale the panel down from its
// top until it fits. The negative margin hands the freed height back to the
// layout so <main> has nothing left to scroll. Draw sizes its own board and
// More is a scrolling page, so neither is scaled.
const FIT_SELECTOR = ':scope > :is(.jackpot-hero, .play-grid), .quest-banner';
let fitFrame = 0;

function clearFit(element) {
  element.style.removeProperty('transform');
  element.style.removeProperty('transform-origin');
  element.style.removeProperty('margin-bottom');
  delete element.dataset.mpagerFit;
}

function fitPage() {
  fitFrame = 0;
  if (!main) return;
  for (const element of main.querySelectorAll('[data-mpager-fit]')) clearFit(element);
  if (!phone.matches || current === 'draw' || current === 'more') return;
  const panel = [...main.querySelectorAll(FIT_SELECTOR)].find((element) => element.offsetHeight > 0);
  if (!panel) return;
  const overflow = main.scrollHeight - main.clientHeight;
  if (overflow <= 1) return;
  const height = panel.offsetHeight;
  const scale = (height - overflow) / height;
  if (!(scale >= FIT_MIN_SCALE)) return;
  panel.dataset.mpagerFit = scale.toFixed(3);
  panel.style.transformOrigin = 'top center';
  panel.style.transform = `scale(${scale})`;
  panel.style.marginBottom = `${-(height - height * scale)}px`;
}

function scheduleFit() {
  if (fitFrame) return;
  fitFrame = requestAnimationFrame(fitPage);
}

// ---- Dock height ---------------------------------------------------------

function syncDockHeight() {
  const height = phone.matches && dock ? dock.getBoundingClientRect().height : 0;
  document.documentElement.style.setProperty('--mpager-dock-h', `${Math.ceil(height)}px`);
}

// ---- Visible area ----------------------------------------------------------

// Popups are fixed to the layout viewport, but a phone keyboard shrinks only
// the visual viewport on iOS (and pans it), so a centred dialog ends up half
// under the keys. Publish the visible box as CSS variables for the phone
// overlay rules, and keep a focused field inside an overlay in view.
const OVERLAY_SELECTOR = [
  '.panel-popup', '.qst-action-dialog', '.df-reverse-dialog', '.pass-deity-dialog',
  '.pass-afking__dialog', '.deg-referral-dialog', '.records-bounty-dialog',
  '.dec-builder-popover', '.craps-dialog', '.pfd-backdrop',
  '.mobile-event-sheet', '.rvl-backdrop', '.baf-res-modal', '.decimator-draw-modal',
].join(', ');
const KEYBOARD_MIN_PX = 120;
let visibleTallest = 0;
let visibleWidth = 0;
let visibleFrame = 0;

function revealFocusedField() {
  const field = document.activeElement;
  if (!field?.matches?.('input, textarea, select, [contenteditable="true"]')) return;
  const overlay = field.closest(OVERLAY_SELECTOR);
  if (!overlay) return;
  // Innermost scroller first, so each outer one sees the field where the
  // inner one left it.
  for (let el = field.parentElement; el; el = el.parentElement) {
    const style = getComputedStyle(el);
    if (el.scrollHeight > el.clientHeight + 1 && /(auto|scroll)/.test(style.overflowY)) {
      const box = el.getBoundingClientRect();
      const target = field.getBoundingClientRect();
      const top = Math.max(box.top, 0);
      const bottom = Math.min(box.bottom, window.visualViewport?.height ?? box.bottom);
      if (target.top < top + 8) el.scrollTop -= top + 8 - target.top;
      else if (target.bottom > bottom - 8) el.scrollTop += target.bottom - (bottom - 8);
    }
    if (el === overlay) break;
  }
}

function syncVisibleArea() {
  visibleFrame = 0;
  const viewport = window.visualViewport;
  const root = document.documentElement;
  if (!phone.matches || !viewport) {
    root.style.removeProperty('--mpager-vv-top');
    root.style.removeProperty('--mpager-vv-h');
    delete root.dataset.mpagerKeyboard;
    return;
  }
  // A new width is a rotation or a resized window: start the tallest over.
  if (Math.round(viewport.width) !== visibleWidth) {
    visibleWidth = Math.round(viewport.width);
    visibleTallest = 0;
  }
  visibleTallest = Math.max(visibleTallest, viewport.height);
  root.style.setProperty('--mpager-vv-top', `${Math.round(viewport.offsetTop)}px`);
  root.style.setProperty('--mpager-vv-h', `${Math.round(viewport.height)}px`);
  const keyboard = viewport.height < visibleTallest - KEYBOARD_MIN_PX;
  if (keyboard) {
    root.dataset.mpagerKeyboard = 'open';
    requestAnimationFrame(revealFocusedField);
  } else delete root.dataset.mpagerKeyboard;
}

function scheduleVisibleArea() {
  if (visibleFrame) return;
  visibleFrame = requestAnimationFrame(syncVisibleArea);
}

// ---- Back closes overlays ----------------------------------------------------

// Android's Back (and the iOS edge swipe) left the app with a popup still up,
// or closed the tab outright. Each open overlay holds one same-URL history
// entry; Back pops it and the innermost overlay gets the Escape its own handler
// already closes it on. An overlay closed any other way takes its entry back
// out. Chrome skips an entry pushed without a recent tap until the player taps
// the page again; a reveal that opens after its receipt is tapped through, and
// an untapped one leaves on Back exactly as it would with no entry.
const BACK_STATE = 'mpagerOverlay';
const BACK_POLL_MS = 1000;
// A reveal opens on its receipt, ~12 s after the tap on Sepolia.
const BACK_WATCH_AFTER_TAP_MS = 20_000;
let backDepth = 0;
let lastTapAt = 0;
let ignorePop = false;

function isShown(element) {
  if (!element.isConnected) return false;
  if (typeof element.checkVisibility === 'function') {
    return element.checkVisibility({ opacityProperty: true, visibilityProperty: true });
  }
  return element.getClientRects().length > 0 && getComputedStyle(element).visibility !== 'hidden';
}

// Modal <dialog>s count wherever they are, including the one shadow-DOM host.
const SHADOW_OVERLAY_HOSTS = 'app-craps-rules';

function modalDialogs(root) {
  try { return [...root.querySelectorAll('dialog:modal')]; } catch (_e) { return []; }
}

function shownOverlays() {
  const overlays = new Set([...document.querySelectorAll(OVERLAY_SELECTOR), ...modalDialogs(document)]);
  for (const host of document.querySelectorAll(SHADOW_OVERLAY_HOSTS)) {
    if (host.shadowRoot) for (const dialog of modalDialogs(host.shadowRoot)) overlays.add(dialog);
  }
  return [...overlays].filter(isShown);
}

function syncBackEntries({ poll = false } = {}) {
  if (!phone.matches || document.visibilityState === 'hidden') return;
  // The scan is ~2 ms on a full page; idle pages with nothing open skip it.
  if (poll && !backDepth && Date.now() - lastTapAt > BACK_WATCH_AFTER_TAP_MS) return;
  const open = shownOverlays().length;
  if (open > backDepth) {
    for (; backDepth < open; backDepth += 1) history.pushState({ ...history.state, [BACK_STATE]: true }, '');
  } else if (open < backDepth) {
    const extra = backDepth - open;
    backDepth = open;
    // router.js's replaceState can overwrite the marker; then the entries stay.
    if (history.state?.[BACK_STATE]) {
      ignorePop = true;
      history.go(-extra);
    }
  }
}

// Taps get an answer within two frames; the poll catches overlays that open
// after an await (a reveal waits for its receipt) or close without a tap.
function scheduleBackSync() {
  lastTapAt = Date.now();
  requestAnimationFrame(() => requestAnimationFrame(() => syncBackEntries()));
}

function onPopState() {
  if (ignorePop) {
    ignorePop = false;
    return;
  }
  if (!backDepth) return;
  backDepth -= 1;
  const shown = shownOverlays();
  const overlay = shown.find((el) => !shown.some((other) => other !== el && el.contains(other)));
  if (!overlay) return;
  overlay.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true, cancelable: true }));
  // A modal <dialog> without its own key handler closes natively on Escape,
  // which a synthetic event does not trigger.
  if (overlay instanceof HTMLDialogElement && overlay.open && isShown(overlay)
    && overlay.dispatchEvent(new Event('cancel', { cancelable: true }))) {
    overlay.close();
  }
}

// ---- Wiring --------------------------------------------------------------

function init() {
  if (!main || !dock) return;
  let restored = null;
  try { restored = sessionStorage.getItem(STORAGE_KEY); } catch (_e) { /* private mode */ }
  if (restored && restored !== current && PAGES.includes(restored)) applyPage(restored);
  dock.addEventListener('click', (event) => {
    const tab = event.target.closest?.('[data-mpager-tab]');
    if (tab) {
      if (tab.dataset.mpagerTab === current) {
        main.scrollTo({ top: 0, behavior: 'smooth' });
      } else showPage(tab.dataset.mpagerTab);
      return;
    }
    if (event.target.closest?.('[data-mpager-pending]')) tapPending();
  });
  main.addEventListener('touchstart', onTouchStart, { passive: true });
  main.addEventListener('touchmove', onTouchMove, { passive: false });
  main.addEventListener('touchend', onTouchEnd, { passive: true });
  main.addEventListener('touchcancel', () => {
    gesture = null;
    clearDrag();
  }, { passive: true });

  document.addEventListener('app-reveal-tray:summary', (event) => renderPending(event.detail));
  const tray = document.querySelector('app-reveal-tray');
  if (tray?.pendingSummary) renderPending(tray.pendingSummary);

  if (typeof ResizeObserver === 'function') {
    new ResizeObserver(syncDockHeight).observe(dock);
    // The panel's border box ignores the fit transform and margin, so this
    // fires on content and viewport changes, never on its own adjustment.
    const fitObserver = new ResizeObserver(scheduleFit);
    fitObserver.observe(main);
    for (const panel of main.querySelectorAll(FIT_SELECTOR)) fitObserver.observe(panel);
  }
  window.visualViewport?.addEventListener('resize', scheduleVisibleArea);
  window.visualViewport?.addEventListener('scroll', scheduleVisibleArea);
  // A reload with a popup open lands on its entry; nothing is open now.
  if (history.state?.[BACK_STATE]) {
    const { [BACK_STATE]: _overlay, ...state } = history.state;
    history.replaceState(state, '');
  }
  document.addEventListener('click', scheduleBackSync, true);
  setInterval(() => syncBackEntries({ poll: true }), BACK_POLL_MS);
  document.addEventListener('keyup', scheduleBackSync, true);
  window.addEventListener('popstate', onPopState);
  // A field tapped while the keyboard is already up gets no resize.
  document.addEventListener('focusin', () => {
    if (document.documentElement.dataset.mpagerKeyboard) requestAnimationFrame(revealFocusedField);
  });
  phone.addEventListener?.('change', () => {
    gesture = null;
    clearDrag();
    syncDockHeight();
    scheduleFit();
    scheduleVisibleArea();
  });
  syncDockHeight();
  scheduleFit();
  syncVisibleArea();
  warmNeighbours();
}

init();
